where
    H: Handler<HI, Output = HO> + Sync + 'static,
    HI: TryFromInput + Sync + 'static,
    HI::Error: 'static,
    HO: IntoHandlerResult + Send + 'static,
{
    async fn handle(&self, update: Update) {
